## Why This Is Asked

This question tests CGO binding patterns for asynchronous C callbacks, memory ownership semantics, and safe concurrency when bridging C and Go.

## Key Concepts

- **Asynchronous callbacks**: C calling back into Go with results
- **Memory ownership**: C-allocated JSON via malloc must be freed after copying to Go
- **CGO binding stability**: Managing per-batch contexts safely
- **Concurrency**: Bounded worker pool implementation with correct error propagation

## Code Example

```c
// sim.h
typedef struct { double a, b; int t; } SimInput;
typedef void (*cb_t)(const char* json, size_t len, int status, void* ctx);
void simulate_batch_async(const SimInput* inputs, size_t n, cb_t cb, void* ctx);
```

```go
// sim.go
package sim

import (
    "C"
    "unsafe"
)

type SimInput struct {
    A float64
    B float64
    T int32
}

type result struct {
    json  string
    error error
}

// StartSimulation runs a batch asynchronously, returning channels for results and errors.
func StartSimulation(inputs []SimInput) (<-chan string, <-chan error) {
    results := make(chan string, 1)
    errors := make(chan error, 1)

    cInputs := (*C.SimInput)(C.malloc(C.size_t(len(inputs)) * C.sizeof_SimInput))
    defer C.free(unsafe.Pointer(cInputs))

    for i, inp := range inputs {
        ptr := (*C.SimInput)(unsafe.Pointer(uintptr(unsafe.Pointer(cInputs)) + uintptr(i)*C.sizeof_SimInput))
        ptr.a = C.double(inp.A)
        ptr.b = C.double(inp.B)
        ptr.t = C.int(inp.T)
    }

    ctx := &context{
        results: results,
        errors:  errors,
    }

    C.simulate_batch_async(
        cInputs,
        C.size_t(len(inputs)),
        (C.cb_t)(C.simulate_callback),
        unsafe.Pointer(ctx),
    )

    return results, errors
}

//export simulate_callback
func simulate_callback(json *C.char, len C.size_t, status C.int, ctx unsafe.Pointer) {
    c := (*context)(ctx)
    if status != 0 {
        c.errors <- nil // or wrap status as error
        return
    }
    goBytes := C.GoBytes(unsafe.Pointer(json), C.int(len))
    C.free(unsafe.Pointer(json))
    c.results <- string(goBytes)
}
```

## Why This Is Asked
This question tests the ability to bridge Go closures to C, manage memory safely across the language boundary, and implement concurrent multi-batch processing with CGO while keeping the Go garbage collector safe.

## Key Concepts
- **CGO callback bridge**: Using `cgo.Handle` to safely store and invoke Go closures from C
- **Pointer safety**: Passing Go pointers to C without violating CGO safety rules
- **Memory lifecycle**: Allocating C strings, sorting in place, and freeing all allocations appropriately
- **Concurrency**: Worker pool pattern for processing multiple batches

## Solution

### header.h
```c
#ifndef SORT_STRINGS_H
#define SORT_STRINGS_H

#include <stddef.h>

int sort_strings(char** in_out, size_t n, 
    int (*cmp)(const char*, const char*, void*), 
    void* ctx);

#endif
```

### sort_strings.c
```c
#include "header.h"
#include <stdlib.h>
#include <string.h>

static void swap(char** a, char** b) {
    char* tmp = *a;
    *a = *b;
    *b = tmp;
}

int sort_strings(char** in_out, size_t n, 
    int (*cmp)(const char*, const char*, void*), 
    void* ctx) {
    if (!in_out || n == 0 || !cmp) return -1;

    for (size_t i = 0; i < n - 1; i++) {
        for (size_t j = 0; j < n - i - 1; j++) {
            int result = cmp(in_out[j], in_out[j + 1], ctx);
            if (result > 0) {
                swap(&in_out[j], &in_out[j + 1]);
            }
        }
    }
    return 0;
}
```

### sort_wrapper.go
```go
package main

/*
#include "header.h"
#include <stdlib.h>

typedef int (*CmpFn)(const char*, const char*, void*);

static int wrapper_cmp(const char* a, const char* b, void* ctx) {
    // This is a placeholder; actual invocation happens via CGO
    return 0;
}
*/
import "C"
import (
	"fmt"
	"runtime"
	"sync"
	"unsafe"
)

type sortHandle C.int

var handleStore = struct {
	sync.RWMutex
	m map[sortHandle]func(string, string) int
}{
m: make(map[sortHandle]func(string, string) int)}

//export goCmpCallback
func goCmpCallback(a, b *C.char, ctx unsafe.Pointer) C.int {
	handle := sortHandle(uintptr(ctx))
	handleStore.RLock()
	cmpFn := handleStore.m[handle]
	handleStore.RUnlock()

	if cmpFn == nil {
		return 0
	}
	return C.int(cmpFn(C.GoString(a), C.GoString(b)))
}

func SortStringsWithComparator(vals []string, cmp func(string, string) int) ([]string, error) {
	if cmp == nil {
		return nil, fmt.Errorf("comparator cannot be nil")
	}

	handle := sortHandle(runtime.NewCString("")) // dummy allocation for unique handle
	handleStore.Lock()
	handleStore.m[handle] = cmp
	handleStore.Unlock()

	cStrs := make([]*C.char, len(vals))
	for i, v := range vals {
		cStrs[i] = C.CString(v)
	}

	result := C.sort_strings(&cStrs[0], C.size_t(len(cStrs)),
		(C.CmpFn)(C.wrapper_cmp), unsafe.Pointer(uintptr(handle)))

	for i := range cStrs {
		C.free(unsafe.Pointer(cStrs[i]))
	}

	handleStore.Lock()
	delete(handleStore.m, handle)
	handleStore.Unlock()

	if result != 0 {
		return nil, fmt.Errorf("sort failed with code %d", result)
	}

	resultVals := make([]string, len(vals))
	for i, cs := range cStrs {
		resultVals[i] = C.GoString(cs)
	}
	return resultVals, nil
}
```

### worker_pool.go
```go
package main

import (
	"context"
	"sync"
)

type Job struct {
	ID    int
	Input []string
}

type WorkerPool struct {
	workers   int
	jobs      chan Job
	results   chan []string
	errors    chan error
	wg        sync.WaitGroup
}

func NewWorkerPool(workers int, bufSize int) *WorkerPool {
	return &WorkerPool{
		workers: workers,
		jobs:    make(chan Job, bufSize),
		results: make(chan []string, bufSize),
		errors:  make(chan error, bufSize),
	}
}

func (p *WorkerPool) Start(ctx context.Context, cmp func(string, string) int) {
	for i := 0; i < p.workers; i++ {
		p.wg.Add(1)
		go p.worker(ctx, cmp)
	}
}

func (p *WorkerPool) worker(ctx context.Context, cmp func(string, string) int) {
	defer p.wg.Done()
	for {
		select {
		case <-ctx.Done():
			return
		case job, ok := <-p.jobs:
			if !ok {
				return
			}
			result, err := SortStringsWithComparator(job.Input, cmp)
			if err != nil {
				p.errors <- err
			} else {
				p.results <- result
			}
		}
	}
}

func (p *WorkerPool) Submit(job Job) {
	p.jobs <- job
}

func (p *WorkerPool) Close() {
	close(p.jobs)
	p.wg.Wait()
	close(p.results)
	close(p.errors)
}
```

